targets.query:
from(bucket: "tani_bucket")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r["_measurement"] == "sensordata")
  |> filter(fn: (r) => r["_field"] == "voltage")
  |> map(fn: (r) => ({
      // Keep all existing columns
      r with 
      // Add a new field for percentage
      _value: (r._value - 3.2) / (4.2 - 3.2) * 100.0,
      _field: "battery_percent"
  }))
  // Optional: Clamp values between 0 and 100 to avoid "105%" or "-5%"
  |> map(fn: (r) => ({
      r with
      _value: if r._value > 100.0 then 100.0 else if r._value < 0.0 then 0.0 else r._value
  }))
  |> filter(fn: (r) => r["gateway"] == "TaniNet")
  |> filter(fn: (r) => r["node"] == "${node}")
  |> aggregateWindow(every: v.windowPeriod, fn: mean, createEmpty: false)
  |> yield(name: "mean")

